schema:
{
  "description": "Email dei clienti",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "Mittente": {
        "type": "string",
        "method": "extract",
        "description": "Indirizzo nell'intestazione \"Da\"."
      },
      "DataInvio": {
        "type": "date",
        "method": "extract",
        "description": "Data nell'intestazione \"Data\"."
      },
      "NumeroPratica": {
        "type": "string",
        "method": "extract",
        "description": "Codice pratica nel formato PR- seguito da cinque cifre."
      },
      "TipoRichiesta": {
        "type": "string",
        "method": "classify",
        "enum": [
          "reclamo",
          "ordine",
          "informazioni",
          "disdetta",
          "altro"
        ],
        "description": "Che cosa chiede il cliente nel testo."
      }
    }
  }
}
